            <div class="card-surface overflow-hidden"><div class="flex items-center justify-between border-b border-slate-100 p-5"><div><h2 class="font-display text-lg font-bold">Daftar produk</h2><p class="mt-1 text-xs text-slate-400">Harga beli bisa diperbarui ke data produk.</p></div><button type="button" @click="addItem()" class="rounded-xl bg-teal-50 px-4 py-2.5 text-sm font-bold text-teal-700">+ Tambah produk</button></div><div class="overflow-x-auto"><table class="w-full min-w-[880px] text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-400"><tr><th class="px-5 py-3">Produk</th><th class="px-5 py-3">Jumlah</th><th class="px-5 py-3">Harga beli</th><th class="px-5 py-3 text-right">Subtotal</th><th></th></tr></thead><tbody class="divide-y divide-slate-100"><template x-for="(item, index) in items" :key="item.key"><tr><td class="px-5 py-4"><div class="relative"><input type="hidden" :name="`items[${index}][product_id]`" x-model="item.product_id"><input x-model="item.search" @input.debounce.250ms="searchProducts(item)" placeholder="Cari kode atau nama..." class="w-full rounded-xl border-slate-200"><div x-show="item.options.length" class="absolute left-0 right-0 z-10 mt-1 rounded-xl border border-slate-200 bg-white p-1 shadow-xl"><template x-for="product in item.options" :key="product.id"><button type="button" @click="selectProduct(item, product)" class="block w-full rounded-lg px-3 py-2 text-left text-sm hover:bg-teal-50"><span class="font-bold" x-text="product.name"></span><span class="text-xs text-slate-400" x-text="` · ${product.code} · ${product.unit}`"></span></button></template></div></div></td><td class="w-32 px-5 py-4"><input type="number" min="1" x-model.number="item.qty" :name="`items[${index}][qty]`" class="w-full rounded-xl border-slate-200"></td><td class="w-48 px-5 py-4"><input type="number" min="0" x-model.number="item.buy_price" :name="`items[${index}][buy_price]`" class="w-full rounded-xl border-slate-200"></td><td class="px-5 py-4 text-right font-bold" x-text="format(item.qty * item.buy_price)"></td><td class="px-5 py-4"><button type="button" @click="removeItem(index)" class="rounded-lg px-2 py-1 text-rose-500 hover:bg-rose-50">×</button></td></tr></template></tbody><tfoot class="border-t border-slate-100 bg-slate-50"><tr><td colspan="3" class="px-5 py-4 text-right font-bold">Total</td><td class="px-5 py-4 text-right text-lg font-extrabold text-teal-700" x-text="format(total())"></td><td></td></tr></tfoot></table></div><div class="border-t border-slate-100 p-5"><label class="inline-flex items-center gap-2 text-sm font-semibold"><input type="checkbox" name="update_buy_price" value="1" class="rounded border-slate-300 text-teal-600 focus:ring-teal-500"> Perbarui harga beli produk berdasarkan transaksi ini</label></div></div>
