    @push('scripts')<script>function stockInForm(){return {items:[{key:Date.now(),product_id:'',search:'',qty:1,buy_price:0,options:[]}],submitting:false,init(){}, addItem(){this.items.push({key:Date.now()+Math.random(),product_id:'',search:'',qty:1,buy_price:0,options:[]})},removeItem(index){if(this.items.length>1)this.items.splice(index,1)},selectProduct(item,product){item.product_id=product.id;item.search=product.name+' ('+product.code+')';item.buy_price=product.buy_price;item.options=[]},async searchProducts(item){if(item.search.length<2){item.options=[];return}const response=await fetch('{{ route('stock-ins.autocomplete') }}?q='+encodeURIComponent(item.search));item.options=await response.json()},total(){return this.items.reduce((sum,item)=>sum+(Number(item.qty)||0)*(Number(item.buy_price)||0),0)},format(value){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value||0)}}}</script>@endpush
